// HR-02 resume-corpus and HR-04 interview-scorecards-question-banks: the
// structural screen over the two drafted artifact sets of people-hr cluster 2.
//
// tests/drafted/hr-c1-drafted-screen.test.js is the model and, through it, the
// operations C1 screen: documents are read lazily inside each test, the CORE-04
// roster is generated in-test rather than read off disk, and every allowed
// capitalized string except a two-phrase, two-word furniture list is derived
// from canon or from generated bytes.
//
// Three things are worth stating before the assertions.
//
// First, `validate` cannot help here. Neither C2 set is deterministic, so there
// is no regeneration diff: a one-byte edit to a committed resume, question or
// scorecard is caught by this file or by nothing. Every arm below therefore has
// a failing witness, and none of them is a shape that cannot go wrong.
//
// Second, every closed list this screen applies is read out of
// `specs/artifact-specs.yaml` rather than typed here: the screening status
// vocabulary, `age_route_lexemes`, the protected-characteristic probe list,
// `required_resume_fields`, the scorecard status vocabulary, and the experience
// band. If the shipped bytes and the published rule ever part company, a count
// moves and an assertion says so. The frozen HR-01 register and the six frozen
// HR-03 transcripts are read from committed bytes and are never edited.
//
// Third, what this file deliberately does NOT know: which resume carries the
// graduation year, which resume is missing a required field, which question
// carries a probe phrase, and which scorecard was never submitted. Those are
// per-instance answer keys and answer keys do not live in this repo
// (canon/companies.md ground rules, restated in datagen/README.md). Every
// assertion below is a cardinality or a shape, recomputed at run time, and each
// plant is pinned beside the number the same rule returns with its qualifier
// dropped, so a corpus that quietly loses its distractors fails too.
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { loadSpecs } from "../../datagen/src/specLoader.js";
import { loadCanonCompanies } from "../../datagen/src/canon.js";
import { generateArtifact } from "../../datagen/src/engine.js";
import { csvTable, fileByPath } from "../helpers/csv-table.js";
import { allowedFrom, unscreenedPhrases, unscreenedWords } from "../helpers/capitalized-screen.js";
import { moneyMatches } from "../helpers/money-shape.js";

const REPO_ROOT = join(import.meta.dirname, "..", "..");
const specs = loadSpecs(join(REPO_ROOT, "specs", "artifact-specs.yaml"));
const canon = loadCanonCompanies(join(REPO_ROOT, "canon", "companies.md"));

const PROTAGONIST = "Atticus Dundee Inc.";
const DRAFTED_IDS = ["HR-02", "HR-04"];
const REQUISITION = "RQN-2026-0105";

/** The formats the two C2 entries declare, pinned so a spec edit has to be deliberate. */
const FORMATS = { "HR-02": "markdown", "HR-04": "json + markdown" };

/** Cluster 1, which this PR reads and never writes. Source counts exclude build/. */
const C1 = {
  "HR-01": { format: "json + markdown", sources: 9 },
  "HR-03": { format: "text", sources: 12 },
  "HR-09": { format: "markdown", sources: 2 },
};

// --------------------------------------------------------------- file access

const artifactDir = (id) => join(REPO_ROOT, "artifacts", id);

function sourceNames(id, predicate) {
  const dir = artifactDir(id);
  assert.ok(existsSync(dir), `${id} is not authored yet: ${dir} does not exist`);
  return readdirSync(dir).filter(predicate).sort();
}

const markdownNames = (id) => sourceNames(id, (n) => n.endsWith(".md"));
const jsonNames = (id) => sourceNames(id, (n) => n.endsWith(".json"));
const readSource = (id, name) => readFileSync(join(artifactDir(id), name), "utf8");
const allMarkdown = (id) => markdownNames(id).map((name) => ({ name, text: readSource(id, name) }));
const allSources = (id) => [...markdownNames(id), ...jsonNames(id)].map((name) => ({ name, text: readSource(id, name) }));

const words = (text) => text.split(/\s+/).filter(Boolean).length;

const register = () => JSON.parse(readSource("HR-01", "role-requisition-register.json"));
const questionBank = () => JSON.parse(readSource("HR-04", "interview-question-bank.json"));
const rubric = () => JSON.parse(readSource("HR-04", "screening-rubric.json"));

// -------------------------------------------------------- the roster, in-test

const roster = () => csvTable(
  fileByPath(generateArtifact(specs.byId.get("CORE-04"), canon), "people-roster.csv").content
).rows;

const fullName = (r) => `${r.first_name} ${r.last_name}`;
const activeRows = () => roster().filter((r) => r.employment_status === "active");
const byId = () => new Map(roster().map((r) => [r.employee_id, r]));
const activeRoleTitles = () => [...new Set(activeRows().map((r) => r.role_title))];
const departments = () => [...new Set(activeRows().map((r) => r.department))];

// ------------------------------------------- the closed lists, read from spec

const featureMatching = (id, pattern) => {
  const found = specs.byId.get(id).planted_features.filter((f) => pattern.test(f));
  assert.equal(found.length, 1, `${id}: expected exactly one planted feature matching ${pattern}`);
  return found[0];
};

const splitList = (text) => text.split(/,\s*/).map((s) => s.trim()).filter(Boolean);

/** The two values the application log's Screening status may take. */
function screeningStatusValues() {
  const feature = featureMatching("HR-02", /^application-log\.md is the recruiter-side record/);
  const list = splitList(feature.match(/Screening status draws from: ([^.]+)\./)[1]);
  assert.equal(list.length, 2, "the spec sentence did not yield a two-value screening vocabulary");
  return list;
}

/** The phrases the corpus is swept against and must return zero hits on. */
function ageRouteLexemes() {
  const feature = featureMatching("HR-02", /^age_route_lexemes is the closed/);
  const list = splitList(feature.match(/word boundaries: ([^.]+)\./)[1]);
  assert.ok(list.length >= 6, "the spec sentence did not yield an age route lexeme list");
  return list;
}

/** The 4 to 12 year band, read off the same sentence rather than restated. */
function experienceBandYears() {
  const feature = featureMatching("HR-02", /^age_route_lexemes is the closed/);
  const m = feature.match(/inside a (\d+) to (\d+) year band/);
  assert.ok(m, "the spec sentence carries no experience band");
  return [Number(m[1]), Number(m[2])];
}

/** The six required resume fields HR-02b is defined against. */
function requiredResumeFields() {
  const feature = featureMatching("HR-04", /^screening-rubric\.json states/);
  const list = splitList(feature.match(/before scoring it: ([^.]+)\./)[1]);
  assert.equal(list.length, 6, `required_resume_fields came out of the spec with ${list.length} entries`);
  return list;
}

/** The protected-characteristic probe list, as {phrase, characteristic}. */
function probePhrases() {
  const feature = featureMatching("HR-04", /^protected_characteristic_probe_list is the closed/);
  const out = [];
  for (const m of feature.matchAll(/\b(age|family_status): ([^.]+)(?:\.|$)/g)) {
    for (const phrase of splitList(m[2])) out.push({ phrase, characteristic: m[1] });
  }
  assert.equal(out.length, 6, `the spec sentence yielded ${out.length} probe phrases, expected 6`);
  return out;
}

/** The two values a scorecard's Status may take. */
function scorecardStatusValues() {
  const feature = featureMatching("HR-04", /^six scorecards, one per frozen interview transcript/);
  const list = splitList(feature.match(/Status draws from: ([^.]+)(?:\.|$)/)[1]);
  assert.equal(list.length, 2, "the spec sentence did not yield a two-value scorecard vocabulary");
  return list;
}

/** HR-01's twelve exclusion phrases, parsed out of the frozen C1 spec sentence. */
function exclusionPhrases() {
  const feature = featureMatching("HR-01", /^exclusion_phrase_list is the closed rule set/);
  const out = [];
  for (const m of feature.matchAll(/\b(age|national_origin|disability|family_status): ([^.]+)(?:\.|$)/g)) {
    for (const phrase of splitList(m[2])) out.push(phrase);
  }
  assert.equal(out.length, 12, `the frozen spec sentence yielded ${out.length} exclusion phrases, expected 12`);
  return out;
}

/** The frozen HR-03 anchor rule's closed technology_vocabulary list. */
function technologyVocabulary() {
  const feature = featureMatching("HR-03", /^technology_vocabulary is the closed list/);
  const list = splitList(feature.match(/HR-01 exclusion list: (.+)$/)[1]);
  assert.equal(list.length, 10, `technology_vocabulary came out of the frozen spec with ${list.length} entries, expected 10`);
  return list;
}

const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
/** Word-bounded, adjacent membership: the way validate's own phrase heuristic matches. */
const carries = (text, token) => new RegExp(`\\b${escapeRegExp(token)}\\b`, "i").test(text);
/** The head word of a probe phrase is its last word, which is what the spec says. */
const headWord = (phrase) => phrase.split(" ").pop();

// ------------------------------------------------------------------- parsers

/**
 * `- Key: value` metadata lines of the block above the first section heading,
 * so an experience bullet reading like a label cannot enter the metadata map.
 */
function metadata(text) {
  const out = new Map();
  for (const line of text.split(/\n## /)[0].split("\n")) {
    const m = line.match(/^- ([A-Z][A-Za-z ]*?):(?: (.*))?$/);
    if (!m) continue;
    out.set(m[1], (m[2] ?? "").trim());
  }
  return out;
}

/** `## Heading` sections, as heading -> body. */
function sections(text) {
  const out = new Map();
  for (const chunk of text.split(/^## /m).slice(1)) {
    const nl = chunk.indexOf("\n");
    out.set(chunk.slice(0, nl).trim(), chunk.slice(nl + 1).trim());
  }
  return out;
}

/** The body of a resume: everything from the first section heading onward. */
function body(text) {
  const i = text.indexOf("\n## ");
  return i === -1 ? "" : text.slice(i);
}

/** Every `| a | b | c |` row of a markdown table, separator rows dropped. */
function tableRows(text) {
  return text.split("\n")
    .filter((l) => l.trim().startsWith("|"))
    .filter((l) => !/^\s*\|[\s|:-]+\|\s*$/.test(l))
    .map((l) => l.split("|").slice(1, -1).map((c) => c.trim()));
}

const YEAR_TOKEN = /\b(19|20)\d\d\b/g;
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

const resumeNames = () => sourceNames("HR-02", (n) => n.startsWith("resume-ca-") && n.endsWith(".md"));
const resumes = () => resumeNames().map((name) => ({ name, text: readSource("HR-02", name) }));
const applicationLog = () => readSource("HR-02", "application-log.md");

const scorecardNames = () => sourceNames("HR-04", (n) => n.startsWith("scorecard-") && n.endsWith(".md"));
const transcriptNames = () => sourceNames("HR-03", (n) => n.startsWith("interview-transcript-") && n.endsWith(".md"));
const pairedTranscript = (scorecard) => scorecard.replace("scorecard-", "interview-transcript-");

// One to twelve, the number words a quantified experience claim may use here.
const CLAIM_NUMBER_WORDS = {
  one: 1, two: 2, three: 3, four: 4, five: 5, six: 6,
  seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12,
};
const CLAIM_YEAR_PHRASE = new RegExp(
  `\\b(\\d+|${Object.keys(CLAIM_NUMBER_WORDS).join("|")})\\s+years?\\b`, "gi"
);

/**
 * The largest integer any sentence of a frozen HR-03 source (feedback files
 * included: a quantified claim's sentence lives in a feedback file) pairs with a
 * technology_vocabulary token, in years, or 0 if no sentence pairs the two.
 */
function largestQuantifiedClaimYears(text, vocabulary) {
  const sentences = text.split(/(?<=[.!?])\s+/);
  let max = 0;
  for (const sentence of sentences) {
    if (!vocabulary.some((tech) => carries(sentence, tech))) continue;
    for (const m of sentence.matchAll(CLAIM_YEAR_PHRASE)) {
      const raw = m[1].toLowerCase();
      const value = CLAIM_NUMBER_WORDS[raw] ?? Number(raw);
      if (value > max) max = value;
    }
  }
  return max;
}

/** The competency ids a frozen transcript says were assessed, in its own order. */
function assessedCompetencies(text, label) {
  const block = text.split("- Competencies assessed:")[1];
  assert.ok(block, `${label}: the transcript carries no competencies assessed block`);
  const ids = block.split("\n\n")[0].split("\n")
    .map((l) => l.match(/^\s+- (.+) \((CMP-\d{2})\)$/)).filter(Boolean).map((m) => m[2]);
  assert.ok(ids.length >= 2, `${label}: fewer than two competencies assessed`);
  return ids;
}

/** The one active row printed as these bytes; an ambiguous join fails on its own. */
function resolveActive(name, roleTitle, context, rows) {
  const matches = rows.filter((r) => fullName(r) === name && r.role_title === roleTitle);
  assert.equal(
    matches.length, 1,
    `${context}: "${name} (${roleTitle})" resolves to ${matches.length} active roster rows, expected exactly 1`
  );
  return matches[0];
}

/** Every candidate name the corpus prints, off the resume titles themselves. */
const candidateNames = () => resumes().map(({ name, text }) => {
  const m = text.match(/^# (.+)$/m);
  assert.ok(m, `${name}: the resume carries no title line`);
  return m[1].trim();
});

// ------------------------------------------------------------------ furniture

// The one place a typed list is allowed. Each entry is here because a document
// has to print it and the pack ships it nowhere else.
const FURNITURE_PHRASES = [
  "Candidate ID",   // the metadata label every resume, log row and scorecard prints
  "Requisition ID", // the same
  "Scorecard ID",   // the same, on the scorecards
];
const FURNITURE_WORDS = [
  "I",   // the first-person pronoun, in a candidate's own summary
  "ID",  // the second word of all three labels above
];

// ------------------------------------------------------------- the freeze gate

test("the C2 freeze gate is exactly two drafted artifact sets, with cluster 1 untouched", () => {
  for (const id of DRAFTED_IDS) {
    const spec = specs.byId.get(id);
    assert.ok(spec, `${id} is not in the spec catalog`);
    assert.equal(spec.generation, "drafted-frozen", `${id} is not drafted-frozen`);
    assert.equal(spec.format, FORMATS[id], `${id} format drifted from the HR block`);
    assert.equal(spec.columns, undefined, `${id} is prose and carries no columns`);
    assert.ok(spec.period, `${id} states no period, so no window is pinned`);
    assert.ok(spec.planted_features.length > 0, `${id} states no planted features for validate to check`);
    assert.deepEqual(spec.canon_entities, ["co-002"], `${id} names a canon entity other than the protagonist`);
  }
  // Cluster 1 is read by this cluster and written by nobody in it.
  for (const [id, expected] of Object.entries(C1)) {
    const spec = specs.byId.get(id);
    assert.equal(spec.generation, "drafted-frozen", `${id} is no longer drafted-frozen`);
    assert.equal(spec.format, expected.format, `${id}'s frozen format line has been edited`);
    const files = sourceNames(id, (n) => n !== "build");
    assert.equal(
      files.length, expected.sources,
      `${id} ships ${files.length} source files, expected the frozen ${expected.sources}`
    );
  }
});

// ------------------------------------------------------------------- HR-C2-T1

test("HR-C2-T1: eighteen resumes, one log, one id set, and the file names agree", () => {
  const names = resumeNames();
  assert.equal(names.length, 18, `HR-02 ships ${names.length} resumes, expected 18`);
  assert.deepEqual(
    markdownNames("HR-02"), ["application-log.md", ...names].sort(),
    "HR-02 ships a markdown source that is neither a resume nor the application log"
  );

  const ids = [];
  for (const { name, text } of resumes()) {
    const meta = metadata(text);
    assert.deepEqual(
      [...meta.keys()], ["Candidate ID", "Requisition ID", "Application date", "Contact"],
      `${name}: the metadata key set has drifted from the uniform order`
    );
    const id = meta.get("Candidate ID");
    assert.equal(name, `resume-${id}.md`, `${name}: the file name and the candidate id disagree`);
    assert.equal(meta.get("Requisition ID"), REQUISITION, `${name}: the corpus spans more than one requisition`);
    ids.push(id);
  }
  assert.equal(new Set(ids).size, 18, "two resumes print the same candidate id");

  const rows = tableRows(applicationLog());
  const logIds = rows.slice(1).map((r) => r[0]);
  assert.equal(logIds.length, 18, `the application log carries ${logIds.length} rows, expected 18`);
  assert.deepEqual([...logIds].sort(), [...ids].sort(), "the log's id set and the resumes' id set differ");

  // The names in the log are the names on the resumes, resume by resume.
  const titles = new Map(resumes().map(({ text }) => [metadata(text).get("Candidate ID"), text.match(/^# (.+)$/m)[1].trim()]));
  for (const row of rows.slice(1)) {
    assert.equal(row[1], titles.get(row[0]), `the log prints "${row[1]}" for ${row[0]}, which is not that resume's own title`);
  }
});

// ------------------------------------------------------------------- HR-C2-T2

test("HR-C2-T2: no candidate is an employee, a canon person, or a co-002 address", () => {
  const rows = roster();
  const rosterFullNames = new Set(rows.map(fullName));
  const surnames = new Set(rows.map((r) => r.last_name));
  const firstNames = new Set(rows.map((r) => r.first_name));
  const employeeIds = new Set(rows.map((r) => r.employee_id));
  assert.equal(surnames.size, 40, `the roster draws on ${surnames.size} surnames; the rule was written against 40`);

  const canonText = readFileSync(join(REPO_ROOT, "canon", "people.md"), "utf8");
  const canonSeated = new Set(
    canonText.split("\n")
      .filter((l) => l.trim().startsWith("| pe-"))
      .map((l) => l.split("|").slice(1, -1).map((c) => c.trim())[1])
      .filter(Boolean)
  );
  assert.ok(canonSeated.size >= 60, `only ${canonSeated.size} canon people were parsed; the parse has broken`);

  const domains = new Set();
  for (const { name, text } of resumes()) {
    const meta = metadata(text);
    const id = meta.get("Candidate ID");
    assert.ok(!employeeIds.has(id), `${name}: the candidate id ${id} is also an employee id`);

    const person = text.match(/^# (.+)$/m)[1].trim();
    assert.ok(!rosterFullNames.has(person), `${name}: the candidate name "${person}" is a roster row`);
    assert.ok(!canonSeated.has(person), `${name}: the candidate name "${person}" is a seated canon person`);
    const parts = person.split(" ");
    assert.equal(parts.length, 2, `${name}: "${person}" is not a First Last name`);
    assert.ok(!surnames.has(parts[1]), `${name}: the surname "${parts[1]}" is one of the roster's forty`);
    assert.ok(!firstNames.has(parts[0]), `${name}: the first name "${parts[0]}" is one of the roster's own`);

    const contact = meta.get("Contact");
    const at = contact.lastIndexOf("@");
    assert.ok(at > 0, `${name}: the contact line is not an address`);
    domains.add(contact.slice(at + 1));
  }
  assert.equal(domains.size, 1, `the corpus uses ${domains.size} contact domains, expected one reserved domain`);
  const domain = [...domains][0];
  assert.ok(domain.endsWith(".example"), `the contact domain ${domain} is not a reserved example domain`);
  assert.notEqual(domain, "co002.example", "candidate addresses sit at the company's own domain");
  assert.equal(
    rows.filter((r) => r.email.endsWith("@co002.example")).length, rows.length,
    "the roster no longer sits entirely at co002.example, so the domain rule proves nothing"
  );
});

// ------------------------------------------------------------------- HR-C2-T3

test("HR-C2-T3: one graduation year against the qualifier-free eighteen, and no age route", () => {
  const [minYears, maxYears] = experienceBandYears();
  const lexemes = ageRouteLexemes();

  let inBodies = 0;
  let withMetadata = 0;
  let inEducation = 0;
  for (const { name, text } of resumes()) {
    const hits = body(text).match(YEAR_TOKEN) ?? [];
    inBodies += hits.length;
    if ((text.match(YEAR_TOKEN) ?? []).length > 0) withMetadata += 1;
    if (hits.length > 0) {
      const education = sections(text).get("Education") ?? "";
      const inSection = (education.match(YEAR_TOKEN) ?? []).length;
      assert.equal(
        inSection, hits.length,
        `${name}: a body year token sits outside the education section`
      );
      inEducation += 1;
    }
    for (const lexeme of lexemes) {
      assert.ok(!carries(text, lexeme), `${name}: carries the age route lexeme "${lexeme}"`);
    }
  }
  assert.equal(inBodies, 1, `${inBodies} four-digit year tokens sit in resume bodies, expected exactly 1`);
  assert.equal(inEducation, 1, `${inEducation} resumes carry a body year token, expected exactly 1`);
  assert.equal(
    withMetadata, 18,
    `${withMetadata} resumes carry a year token with the metadata exclusion dropped, expected 18`
  );

  // The band that makes "the year is the only route" true rather than aspirational.
  for (const { name, text } of resumes()) {
    const experience = sections(text).get("Experience");
    assert.ok(experience, `${name}: no experience section`);
    const entries = experience.split("\n").filter((l) => l.startsWith("### "));
    assert.ok(entries.length >= 2 && entries.length <= 4, `${name}: ${entries.length} experience entries, outside the 2 to 4 band`);
    let months = 0;
    for (const entry of entries) {
      const m = entry.match(/, (\d+) years? (\d+) months?$/);
      assert.ok(m, `${name}: the entry "${entry}" does not end in a duration written as N years M months`);
      months += Number(m[1]) * 12 + Number(m[2]);
    }
    assert.ok(
      months >= minYears * 12 && months <= maxYears * 12,
      `${name}: summed experience is ${Math.floor(months / 12)} years ${months % 12} months, outside the ${minYears} to ${maxYears} year band`
    );
  }

  // Review finding 4: the band's floor is a stand-in for the real rule, which is
  // that each advanced candidate's summed experience also clears the largest
  // single-technology claim the frozen HR-03 corpus records for that candidate
  // (a quantified claim's sentence lives in a feedback file and need not be
  // echoed in its paired transcript, which is exactly what "unanchored" means).
  // This is recomputed here, against the frozen bytes, rather than merely
  // asserted in the allowlist.
  const vocabulary = technologyVocabulary();
  const byCandidate = new Map();
  for (const sourceName of markdownNames("HR-03")) {
    const sourceText = readSource("HR-03", sourceName);
    const id = metadata(sourceText).get("Candidate ID");
    if (!byCandidate.has(id)) byCandidate.set(id, []);
    byCandidate.get(id).push(sourceText);
  }
  assert.equal(byCandidate.size, 2, `${byCandidate.size} candidates carry frozen HR-03 sources, expected the advanced pair of 2`);

  for (const [id, candidateSources] of byCandidate) {
    const resumeText = readSource("HR-02", `resume-${id}.md`);
    const titleLine = resumeText.match(/^# (.+)$/m);
    assert.ok(titleLine, `${id}: the resume carries no title line`);
    const name = titleLine[1].trim();

    const entries = sections(resumeText).get("Experience").split("\n").filter((l) => l.startsWith("### "));
    let candidateMonths = 0;
    for (const entry of entries) {
      const m = entry.match(/, (\d+) years? (\d+) months?$/);
      assert.ok(m, `${name}: the entry "${entry}" does not end in a duration written as N years M months`);
      candidateMonths += Number(m[1]) * 12 + Number(m[2]);
    }

    const largestClaimYears = Math.max(0, ...candidateSources.map((t) => largestQuantifiedClaimYears(t, vocabulary)));
    assert.ok(
      candidateMonths >= largestClaimYears * 12,
      `${name}: summed experience is shorter than the largest single-technology claim the frozen corpus records for this candidate`
    );
  }
});

// ------------------------------------------------------------------- HR-C2-T4

test("HR-C2-T4: one missing required field against the qualifier-free six", () => {
  const fields = requiredResumeFields();
  const required = new Set(fields);
  for (const f of ["summary", "experience", "education", "candidate_id", "full_name", "contact_email"]) {
    assert.ok(required.has(f), `required_resume_fields no longer names ${f}, so this arm is checking the wrong list`);
  }

  const statuses = new Map(tableRows(applicationLog()).slice(1).map((r) => [r[0], r[3]]));
  const sectionUnion = new Set();
  for (const { text } of resumes()) for (const key of sections(text).keys()) sectionUnion.add(key);

  const missingRequired = [];
  const missingSomeSection = [];
  for (const { name, text } of resumes()) {
    const meta = metadata(text);
    const secs = sections(text);
    const has = {
      candidate_id: /^ca-\d{3}$/.test(meta.get("Candidate ID") ?? ""),
      full_name: /^# .+$/m.test(text),
      contact_email: /@/.test(meta.get("Contact") ?? ""),
      summary: (secs.get("Summary") ?? "").length > 0,
      experience: (secs.get("Experience") ?? "").split("\n").filter((l) => l.startsWith("### ")).length >= 2,
      education: (secs.get("Education") ?? "").split("\n").filter((l) => l.startsWith("### ")).length >= 1,
    };
    const absent = fields.filter((f) => has[f] === false);
    if (absent.length > 0) missingRequired.push({ name, absent });
    if ([...sectionUnion].some((s) => !secs.has(s))) missingSomeSection.push(name);
  }

  assert.equal(
    missingRequired.length, 1,
    `${missingRequired.length} resumes lack a required field, expected exactly 1`
  );
  assert.equal(
    missingRequired[0].absent.length, 1,
    `the selected resume lacks ${missingRequired[0].absent.length} required fields, expected exactly 1`
  );
  assert.equal(
    missingSomeSection.length, 6,
    `${missingSomeSection.length} resumes are missing a section the corpus otherwise carries, expected the stated 6`
  );

  // The missing field feeds a weighted criterion, which is what makes the resume
  // score incomplete rather than merely short.
  const evidenceSources = new Set(rubric().criteria.map((c) => c.evidence_source));
  assert.ok(
    evidenceSources.has(missingRequired[0].absent[0]),
    `the missing field ${missingRequired[0].absent[0]} feeds no weighted criterion, so the resume is merely short`
  );

  // The two selections are different resumes, and both sit in the pending pool.
  const withYear = resumes().filter(({ text }) => (body(text).match(YEAR_TOKEN) ?? []).length > 0);
  assert.equal(withYear.length, 1, "the year selection has moved, so this arm cannot compare the two");
  assert.notEqual(
    withYear[0].name, missingRequired[0].name,
    "the two plants land on the same resume, so one rewrite would close both"
  );
  const [advanced, pending] = screeningStatusValues();
  assert.ok(advanced && pending, "the screening vocabulary did not resolve");
  for (const name of [withYear[0].name, missingRequired[0].name]) {
    const id = metadata(readSource("HR-02", name)).get("Candidate ID");
    assert.equal(statuses.get(id), pending, `${name} does not carry "${pending}", so the showcase would not contain it`);
  }
});

