test("HR-C2-T5: the funnel, its window, its two-value vocabulary and its advanced pair", () => {
  const spec = specs.byId.get("HR-02");
  const values = screeningStatusValues();
  const [advanced, pending] = values;
  const log = applicationLog();
  const meta = metadata(log);
  assert.deepEqual(
    [...meta.keys()],
    ["Requisition ID", "Requisition title", "Applications received", "Application window",
      "Screening approach", "Shortlist decision due", "Recruiter"],
    "the application log's metadata key set has drifted"
  );

  const reg = register();
  const req = reg.requisitions.find((r) => r.requisition_id === REQUISITION);
  assert.ok(req, "the corpus attaches to a requisition the frozen register does not carry");
  assert.equal(req.status, "open", "the requisition the corpus attaches to is not open");
  assert.equal(meta.get("Requisition title"), req.requisition_title, "the log's title is not the register's own");
  assert.equal(meta.get("Requisition ID"), REQUISITION, "the log names another requisition");
  assert.equal(meta.get("Applications received"), "18", "the log's stated count is not 18");
  assert.equal(meta.get("Shortlist decision due"), spec.period.end, "the decision due date is not the spec period end");
  assert.equal(meta.get("Application window"), `${spec.period.start} to 2026-03-20`, "the stated window is not the spec's own");

  const recruiter = meta.get("Recruiter").match(/^(.+) \(([^()]+)\)$/);
  assert.ok(recruiter, "the recruiter line is not a name and role title");
  const row = resolveActive(recruiter[1], recruiter[2], "the application log recruiter", activeRows());
  assert.equal(row.employee_id, req.recruiter_employee_id, "the log's recruiter is not the requisition's own recruiter");

  const rows = tableRows(log);
  assert.deepEqual(
    rows[0], ["Candidate ID", "Name", "Application date", "Screening status"],
    "the application log carries a column the four-column rule does not allow"
  );

  const byStatus = {};
  let previous = "";
  for (const [id, , date, status] of rows.slice(1)) {
    assert.match(date, ISO_DATE, `${id}: the application date is not an ISO date`);
    assert.ok(date >= spec.period.start, `${id} applied on ${date}, before the window opened`);
    assert.ok(date <= "2026-03-20", `${id} applied on ${date}, after the window closed`);
    assert.ok(date >= req.opened_date, `${id} applied on ${date}, before the requisition was raised on ${req.opened_date}`);
    assert.ok(date >= previous, `${id} breaks the application-date ordering of the table`);
    previous = date;
    assert.ok(values.includes(status), `${id} carries the screening status "${status}", which the vocabulary does not hold`);
    (byStatus[status] ??= []).push(id);
    // Each resume prints the same application date the log does.
    const own = metadata(readSource("HR-02", `resume-${id}.md`)).get("Application date");
    assert.equal(own, date, `${id}: the resume and the log disagree about the application date`);
  }
  for (const value of values) {
    assert.ok(!/shortlist|reject|declin|hire|offer/i.test(value), `the vocabulary carries "${value}", which decides the exercise`);
  }
  assert.equal((byStatus[advanced] ?? []).length, 2, `${(byStatus[advanced] ?? []).length} applications advanced, expected 2`);
  assert.equal((byStatus[pending] ?? []).length, 16, `${(byStatus[pending] ?? []).length} applications are pending, expected 16`);

  const interviewed = [...new Set(transcriptNames().map((n) => metadata(readSource("HR-03", n)).get("Candidate ID")))].sort();
  assert.deepEqual(
    [...byStatus[advanced]].sort(), interviewed,
    "the advanced set is not the candidate set the frozen interview corpus carries"
  );
});

