test("HR-C2-T6: one probe question against the qualifier-free four, every question mapped", () => {
  const bank = questionBank();
  const probes = probePhrases();
  const heads = probes.map((p) => headWord(p.phrase));
  assert.equal(new Set(heads).size, heads.length, "two probe phrases share a head word, so the distractor rule is ambiguous");

  assert.deepEqual(
    Object.keys(bank),
    ["bank_id", "as_of", "source_artifact", "competency_source", "protected_characteristic_probe_list", "panel_roles", "questions"],
    "the question bank's top-level key order has drifted from the documented one"
  );
  const reg = register();
  assert.equal(bank.as_of, reg.as_of, "the bank's as-of has drifted from the frozen register's own");
  assert.deepEqual(
    bank.protected_characteristic_probe_list.map((p) => `${p.characteristic}/${p.phrase}`).sort(),
    probes.map((p) => `${p.characteristic}/${p.phrase}`).sort(),
    "the shipped probe list and the spec's have parted company"
  );

  // The probe list is a rule set of its own, not a second copy of HR-01's.
  const exclusion = exclusionPhrases().map((p) => p.toLowerCase());
  for (const { phrase } of probes) {
    assert.ok(!exclusion.includes(phrase.toLowerCase()), `the probe list repeats the exclusion phrase "${phrase}"`);
  }

  assert.equal(bank.questions.length, 37, `the bank holds ${bank.questions.length} questions, expected 37`);
  const library = new Set(reg.competency_library.map((c) => c.competency_id));
  const perCompetency = {};
  bank.questions.forEach((q, i) => {
    assert.deepEqual(
      Object.keys(q),
      ["question_id", "competency_id", "question_text", "follow_up", "question_type", "panel_role"],
      "a question's key order has drifted from the documented one"
    );
    assert.equal(q.question_id, `QST-${String(i + 1).padStart(4, "0")}`, "the question ids are not sequential from QST-0001 in file order");
    assert.ok(library.has(q.competency_id), `${q.question_id} names ${q.competency_id}, which the frozen library does not carry`);
    assert.ok(q.question_text.trim() && q.follow_up.trim(), `${q.question_id} carries an empty text or follow up`);
    perCompetency[q.competency_id] = (perCompetency[q.competency_id] ?? 0) + 1;
  });
  for (const id of library) {
    assert.ok(perCompetency[id] >= 1, `${id} is covered by no question at all`);
    assert.ok(perCompetency[id] >= 3, `${id} carries ${perCompetency[id]} questions, below the three every competency gets`);
  }
  const fours = Object.entries(perCompetency).filter(([, n]) => n === 4);
  assert.equal(fours.length, 1, `${fours.length} competencies carry a fourth question, expected exactly 1`);
  assert.equal(
    Object.values(perCompetency).filter((n) => n > 4).length, 0,
    "a competency carries more than four questions, so the fourth is no longer the only extra"
  );

  const withPhrase = [];
  const headWordOnly = [];
  for (const q of bank.questions) {
    const hits = probes.filter((p) => carries(q.question_text, p.phrase));
    if (hits.length > 0) {
      withPhrase.push(q.question_id);
      assert.equal(hits.length, 1, `${q.question_id} carries ${hits.length} listed probe phrases, expected at most 1`);
      continue;
    }
    if (heads.some((h) => carries(q.question_text, h))) headWordOnly.push(q.question_id);
  }
  assert.equal(withPhrase.length, 1, `${withPhrase.length} questions carry a full probe phrase, expected exactly 1`);
  assert.equal(
    headWordOnly.length, 4,
    `${headWordOnly.length} questions carry a probe phrase's head word and no listed phrase, expected the stated 4`
  );

  // The probe is the extra question on the one competency carrying four rather
  // than three, so removing it leaves that competency covered and the approved
  // replacement restores a count.
  const probeQuestion = bank.questions.find((q) => q.question_id === withPhrase[0]);
  assert.equal(
    perCompetency[probeQuestion.competency_id], 4,
    "the probe question does not sit on the competency that carries four questions"
  );
  assert.ok(library.has(probeQuestion.competency_id), "the probe question's competency does not resolve in the library");
});

