test("HR-C2-T7: the panel-role map reproduces the frozen transcripts' own competency sets", () => {
  const bank = questionBank();
  const ids = new Set(bank.questions.map((q) => q.question_id));
  assert.equal(bank.panel_roles.length, 3, `panel_roles holds ${bank.panel_roles.length} entries, expected 3`);

  const frozen = new Map();
  for (const name of transcriptNames()) {
    const m = name.match(/^interview-transcript-ca-\d{3}-(.+)\.md$/);
    assert.ok(m, `${name}: the transcript file name does not carry a panel role`);
    const set = assessedCompetencies(readSource("HR-03", name), name).join(",");
    if (frozen.has(m[1])) {
      assert.equal(frozen.get(m[1]), set, `${m[1]}: the two frozen transcripts assess different competency sets`);
    }
    frozen.set(m[1], set);
  }
  assert.equal(frozen.size, 3, `the frozen corpus carries ${frozen.size} panel roles, expected 3`);

  const covered = new Set();
  for (const entry of bank.panel_roles) {
    assert.deepEqual(
      Object.keys(entry), ["panel_role", "competency_ids", "question_ids"],
      "a panel role entry's key order has drifted"
    );
    assert.ok(frozen.has(entry.panel_role), `panel_roles names "${entry.panel_role}", which no frozen transcript carries`);
    assert.equal(
      entry.competency_ids.join(","), frozen.get(entry.panel_role),
      `${entry.panel_role}: the published competency set is not the frozen transcript's own`
    );
    for (const id of entry.competency_ids) covered.add(id);

    const derived = bank.questions.filter((q) => q.panel_role === entry.panel_role).map((q) => q.question_id);
    assert.ok(derived.length > 0, `${entry.panel_role} carries no questions at all`);
    assert.deepEqual(
      entry.question_ids, derived,
      `${entry.panel_role}: the declared question list is not the set of questions carrying that role`
    );
    for (const id of entry.question_ids) {
      assert.ok(ids.has(id), `${entry.panel_role} names ${id}, which the bank does not carry`);
      const q = bank.questions.find((x) => x.question_id === id);
      assert.ok(
        entry.competency_ids.includes(q.competency_id),
        `${id} sits on ${q.competency_id}, which ${entry.panel_role} does not assess`
      );
    }
  }
  // A question outside every panel's reach carries an empty panel role, and one
  // inside a panel's reach never does.
  for (const q of bank.questions) {
    if (q.panel_role === "") {
      assert.ok(!covered.has(q.competency_id), `${q.question_id} carries no panel role but sits on ${q.competency_id}, which a panel assesses`);
    } else {
      assert.ok(covered.has(q.competency_id), `${q.question_id} carries a panel role on a competency no panel assesses`);
    }
  }
});

