test("HR-C2-T8: the rubric's weights, its education criterion and its recomputed maximum", () => {
  const r = rubric();
  assert.deepEqual(
    Object.keys(r),
    ["rubric_id", "as_of", "source_artifact", "requisition_id", "required_resume_fields",
      "scoring_scale", "criteria", "total_possible_score", "shortlist_guidance"],
    "the rubric's top-level key order has drifted from the documented one"
  );
  assert.equal(r.as_of, register().as_of, "the rubric's as-of has drifted from the frozen register's own");
  assert.equal(r.requisition_id, REQUISITION, "the rubric scores a different requisition from the one the corpus applies to");

  assert.deepEqual(
    r.required_resume_fields.map((f) => f.field), requiredResumeFields(),
    "the shipped required-field list and the spec's have parted company"
  );
  assert.equal(r.scoring_scale.min, 0, "the scale does not start at 0");
  assert.equal(r.scoring_scale.max, 4, "the scale does not end at 4");
  assert.equal(
    r.scoring_scale.labels.length, r.scoring_scale.max - r.scoring_scale.min + 1,
    "the scale does not carry a label at every point"
  );

  const competencies = register().requisitions.find((x) => x.requisition_id === REQUISITION).competencies;
  assert.equal(r.criteria.length, 5, `the rubric holds ${r.criteria.length} criteria, expected 5`);
  r.criteria.forEach((c, i) => {
    assert.deepEqual(
      Object.keys(c), ["criterion_id", "name", "definition", "competency_id", "weight", "evidence_source"],
      "a criterion's key order has drifted"
    );
    assert.equal(c.criterion_id, `RUB-0${i + 1}`, "the criterion ids are not sequential from RUB-01 in file order");
    assert.ok(competencies.includes(c.competency_id), `${c.criterion_id} names ${c.competency_id}, which the requisition does not carry`);
    assert.ok(["summary", "experience", "education"].includes(c.evidence_source), `${c.criterion_id} draws on ${c.evidence_source}`);
  });
  assert.equal(
    new Set(r.criteria.map((c) => c.competency_id)).size, competencies.length,
    "the criteria are not one to one with the requisition's competencies"
  );

  const weights = r.criteria.map((c) => c.weight);
  assert.equal(new Set(weights).size, weights.length, "two criteria carry the same weight, so a mis-weighting is undetectable");
  const sum = weights.reduce((a, w) => a + w, 0);
  assert.equal(
    r.total_possible_score, sum * r.scoring_scale.max,
    `total_possible_score is ${r.total_possible_score}, and the weight sum times the scale maximum is ${sum * r.scoring_scale.max}`
  );

  const education = r.criteria.filter((c) => c.evidence_source === "education");
  assert.equal(education.length, 1, `${education.length} criteria draw on education, expected exactly 1`);
  assert.ok(
    education[0].weight > Math.min(...weights) && education[0].weight < Math.max(...weights),
    `the education criterion's weight ${education[0].weight} is not strictly between ${Math.min(...weights)} and ${Math.max(...weights)}`
  );
});

