test("HR-C2-T9: one unsubmitted scorecard against the qualifier-free four", () => {
  const values = scorecardStatusValues();
  const [submitted, notSubmitted] = values;
  const outstanding = [];
  const withEmptyCell = [];

  for (const name of scorecardNames()) {
    const text = readSource("HR-04", name);
    const meta = metadata(text);
    const status = meta.get("Status");
    assert.ok(values.includes(status), `${name}: the status "${status}" is not in the published vocabulary`);
    const rows = tableRows(sections(text).get("Competency ratings")).slice(1);
    assert.ok(rows.length >= 2, `${name}: fewer than two competency rows`);
    const observations = sections(text).get("Additional observations") ?? "";
    const empty = rows.some((r) => r[1] === "" || r[2] === "") || observations === "";
    if (empty) withEmptyCell.push(name);

    if (status === notSubmitted) {
      outstanding.push(name);
      for (const r of rows) {
        assert.equal(r[1], "", `${name}: an outstanding scorecard carries a rating`);
        assert.equal(r[2], "", `${name}: an outstanding scorecard carries evidence`);
      }
      assert.equal(meta.get("Submitted date"), "", `${name}: an outstanding scorecard carries a submitted date`);
      continue;
    }
    const date = meta.get("Submitted date");
    assert.match(date, ISO_DATE, `${name}: the submitted date is not an ISO date`);
    assert.ok(date >= meta.get("Interview date"), `${name}: submitted on ${date}, before the interview it reports on`);
    for (const r of rows) {
      assert.match(r[1], /^[0-4]$/, `${name}: the rating "${r[1]}" is outside the 0 to 4 scale`);
      assert.ok(r[2].length > 0, `${name}: a rated row carries no evidence`);
    }
  }
  assert.equal(outstanding.length, 1, `${outstanding.length} scorecards are outstanding, expected exactly 1`);
  assert.equal(
    withEmptyCell.length, 4,
    `${withEmptyCell.length} scorecards carry an empty cell somewhere, expected the stated 4`
  );
  assert.ok(submitted, "the scorecard vocabulary did not resolve");
});

