test("HR-C2-T10: the six scorecards pair with the frozen transcripts and carry the roster join", () => {
  const cards = scorecardNames();
  const transcripts = transcriptNames();
  assert.equal(cards.length, 6, `HR-04 ships ${cards.length} scorecards, expected 6`);
  assert.deepEqual(
    cards.map(pairedTranscript), transcripts,
    "a scorecard has no transcript of the same name, so the pairing is not resolvable from the file names"
  );

  const spec = specs.byId.get("HR-04");
  const active = activeRows();
  const rows = byId();
  const named = new Map(register().competency_library.map((c) => [c.competency_id, c.name]));

  cards.forEach((name, i) => {
    const text = readSource("HR-04", name);
    const meta = metadata(text);
    assert.deepEqual(
      [...meta.keys()],
      ["Scorecard ID", "Candidate ID", "Requisition ID", "Panel role", "Interviewer",
        "Panelist employee ID", "Interview date", "Requested date", "Status", "Submitted date"],
      `${name}: the metadata key set has drifted from the uniform order`
    );
    assert.equal(
      meta.get("Scorecard ID"), `SCD-2026-${String(i + 1).padStart(4, "0")}`,
      `${name}: the scorecard ids are not sequential from SCD-2026-0001 in file order`
    );

    const transcript = readSource("HR-03", pairedTranscript(name));
    const tMeta = metadata(transcript);
    for (const key of ["Candidate ID", "Requisition ID"]) {
      assert.equal(meta.get(key), tMeta.get(key), `${name}: the ${key} line disagrees with its own transcript`);
    }
    assert.equal(meta.get("Requisition ID"), REQUISITION, `${name}: the scorecard names another requisition`);
    assert.equal(meta.get("Interview date"), tMeta.get("Date"), `${name}: the interview date is not the paired transcript's own date`);
    assert.equal(meta.get("Interviewer"), tMeta.get("Interviewer"), `${name}: the interviewer line is not the transcript's own line`);
    assert.ok(
      meta.get("Interview date") >= spec.period.start && meta.get("Interview date") <= spec.period.end,
      `${name}: the interview date sits outside the spec period`
    );
    assert.ok(name.includes(meta.get("Panel role")), `${name}: the panel role and the file name disagree`);
    assert.match(meta.get("Requested date"), ISO_DATE, `${name}: the requested date is not an ISO date`);

    // The join the frozen interview corpus cannot make, because it carries no employee id.
    const printed = meta.get("Interviewer").match(/^(.+) \(([^()]+)\)$/);
    assert.ok(printed, `${name}: the interviewer line is not "Name (Role Title)"`);
    const expected = resolveActive(printed[1], printed[2], `${name} interviewer`, active);
    const row = rows.get(meta.get("Panelist employee ID"));
    assert.ok(row, `${name}: the panelist employee id does not resolve to a roster row`);
    assert.equal(row.employment_status, "active", `${name}: the panelist has left the company`);
    assert.equal(row.employee_id, expected.employee_id, `${name}: the employee id is not the row the interviewer line names`);

    // One row per competency the paired transcript says was assessed, printed
    // under the frozen library's own name for it.
    const table = tableRows(sections(text).get("Competency ratings"));
    assert.deepEqual(table[0], ["Competency", "Rating", "Evidence"], `${name}: the ratings table columns have drifted`);
    const printedIds = table.slice(1).map((r) => (r[0].match(/\((CMP-\d{2})\)$/) ?? [])[1]);
    assert.deepEqual(
      printedIds, assessedCompetencies(transcript, pairedTranscript(name)),
      `${name}: the competency rows are not the set the paired transcript assessed`
    );
    for (const r of table.slice(1)) {
      const m = r[0].match(/^(.+) \((CMP-\d{2})\)$/);
      assert.equal(m[1], named.get(m[2]), `${name}: ${m[2]} is printed under a name the frozen library does not carry`);
    }

    // The panel form records; it does not decide.
    assert.ok(
      !/\b(recommend|recommendation|hire|no hire|advance|reject|overall score|total score)\b/i.test(text),
      `${name}: the scorecard states a verdict, which belongs to whoever assembles the packet`
    );
  });
});

