test("HR-C2-T12: no em dash, no money, no percentage, and every capitalized string accounted for", () => {
  const sources = [];
  for (const id of DRAFTED_IDS) sources.push(...allSources(id).map(({ name, text }) => [`${id}/${name}`, text]));
  assert.ok(sources.length > 0, "no C2 source was read, so this screen proves nothing");
  for (const [label, text] of sources) {
    assert.ok(!text.includes("—"), `${label} carries an em dash`);
    assert.deepEqual(moneyMatches(text), [], `${label} states a figure, and this cluster carries no money`);
    assert.deepEqual(text.match(/\d+(\.\d+)?\s?%/g) ?? [], [], `${label} states a percentage`);
  }

  // A work location or a date of birth would arrive either as an unaccounted
  // proper noun or as an age route lexeme, and both are screened: the lexemes in
  // T3, the proper nouns here.
  const allowed = allowedFrom({
    derived: [
      PROTAGONIST,
      ...activeRoleTitles(),
      ...departments(),
      ...activeRows().map(fullName),
      ...candidateNames(),
    ],
    furniturePhrases: FURNITURE_PHRASES,
    furnitureWords: FURNITURE_WORDS,
  });
  for (const id of DRAFTED_IDS) {
    for (const { name, text } of allMarkdown(id)) {
      assert.deepEqual(unscreenedPhrases(text, allowed), [], `unscreened capitalized phrase(s) in ${id}/${name}`);
      assert.deepEqual(unscreenedWords(text, allowed), [], `unscreened capitalized word(s) in ${id}/${name}`);
    }
  }
});

test("no departed roster employee and no other canon company is named in either C2 set", () => {
  const rows = roster();
  const live = new Set(rows.filter((r) => r.employment_status === "active").map(fullName));
  const departed = [...new Set(rows.filter((r) => r.employment_status !== "active").map(fullName))]
    .filter((name) => !live.has(name));
  assert.ok(departed.length > 0, "the roster carries no departed employees, so this screen proves nothing");
  for (const id of DRAFTED_IDS) {
    for (const { name, text } of allSources(id)) {
      for (const person of departed) {
        assert.ok(!text.includes(person), `${id}/${name} names ${person}, who has left the company`);
      }
      for (const company of canon.values()) {
        if (company.name === PROTAGONIST) continue;
        assert.ok(!text.includes(company.name), `${id}/${name} names canon company "${company.name}"`);
      }
    }
  }
});

test("HR-02 sits in its word bands and no prior employer or institution is named", () => {
  for (const { name, text } of resumes()) {
    const count = words(text);
    assert.ok(count >= 250 && count <= 400, `${name} runs ${count} words, outside the 250 to 400 band`);
    const order = [...sections(text).keys()];
    assert.equal(order[0], "Summary", `${name}: the first section is ${order[0]}, not the summary`);
    assert.equal(order[1], "Experience", `${name}: the second section is ${order[1]}, not the experience`);
    assert.ok(order.length <= 4, `${name} carries ${order.length} sections, more than the four the form allows`);
    assert.deepEqual(
      order.filter((s) => !["Summary", "Experience", "Education", "Certifications"].includes(s)), [],
      `${name} carries a section the form does not name`
    );
    const summary = words(sections(text).get("Summary"));
    assert.ok(summary >= 40 && summary <= 80, `${name}: the summary runs ${summary} words, outside the 40 to 80 band`);
  }
  // The one company the corpus names is the protagonist, and it names it nowhere,
  // because these are the candidates' own documents. The proper-noun screen in
  // T12 is what makes the absence of employer names mechanical rather than a
  // matter of trust: an employer or an institution would be capitalized.
  const named = resumes().filter(({ text }) => text.includes(PROTAGONIST));
  assert.equal(named.length, 0, "a resume names the hiring company, which a candidate's own document would not");
});
